export type DemoAssemblyPart = AssemblyPart & { center: [number, number, number] };


type RawPart = Omit<DemoAssemblyPart, 'explosionVector' | 'center' | 'role'> & {
  explosionVector: number[];
  center: number[];
  role: string;
};


function demoPart(raw: RawPart): DemoAssemblyPart {
  const [x, y, z] = raw.explosionVector;
  const [cx, cy, cz] = raw.center;
  return {
    ...raw,
    role: raw.role as AssemblyPart['role'],
    explosionVector: [x ?? 0, y ?? 1, z ?? 0],
    center: [cx ?? 0, cy ?? 0, cz ?? 0],
  };
}


